const originalText = new WeakMap<Text, string>();
const originalAttrs = new WeakMap<Element, Map<string, string>>();

export function LanguageSelector() {
  const [language, setLanguage] = useState<Language>("en");
  useEffect(() => {
    const saved = window.localStorage.getItem("quantum-lab-language");
    const selected = languages.find(x => x.code === saved)?.code;
    if (selected) setLanguage(selected);
  }, []);
  useEffect(() => {
    document.documentElement.lang = language;
    localStorage.setItem("quantum-lab-language", language);
    const translate = () => {
      // Keep lab content in English; site navigation remains multilingual.
      const isLabPage = (window.location.pathname === "/lab" || window.location.pathname.startsWith("/lab/"));
      const isEnglishOnlyLab = (element: Element | null) =>
        Boolean(element?.closest("#quantum-lab, [data-lab-english-only]")) ||
        (isLabPage && Boolean(element?.closest("main")));
      // Refresh the source when React replaces a previously translated text node.

      document.querySelectorAll("body").forEach(root => {
        const walker = document.createTreeWalker(root, NodeFilter.SHOW_TEXT);
        let node: Node | null;
        while ((node = walker.nextNode())) {
          if (node.parentElement?.closest("[data-language-selector],script,style,textarea,input,code,pre")) continue;
          const el = node as Text;
          const current = el.textContent ?? "";
          const cached = originalText.get(el);
          const original = cached === undefined || (current !== cached && !Object.values(dictionary).some(d => Object.entries(d).some(([key, translated]) => current.trim() === translated || current.trim() === key))) ? current : cached;
          originalText.set(el, original);
          const key = original.trim();
          const exact = normalizedTranslation(key, language);
          const upperKey = Object.keys(dictionary[language] ?? {}).find(k => k.toUpperCase() === key.toUpperCase());
          const translation = exact ?? (upperKey ? (key === key.toUpperCase() ? dictionary[language]?.[upperKey]?.toUpperCase() : dictionary[language]?.[upperKey]) : undefined);
          const restoreEnglish = isEnglishOnlyLab(node.parentElement);
          const sourceEnglish = normalizedTranslation(key, "en");
          const next = restoreEnglish ? (sourceEnglish ? original.replace(key, sourceEnglish) : original) : (translation ? original.replace(key, translation) : original);
          if (el.textContent !== next) el.textContent = next;
        }
      });
      document.querySelectorAll<HTMLElement>("[placeholder],[title],[aria-label],[alt]").forEach(el => {
        if (el.closest("[data-language-selector],script,style,code,pre")) return;
        let originals = originalAttrs.get(el);
        if (!originals) { originals = new Map(); originalAttrs.set(el, originals); }
        for (const attr of ["placeholder", "title", "aria-label", "alt"]) {
          if (!el.hasAttribute(attr)) continue;
          const currentAttr = el.getAttribute(attr) ?? "";
          const cachedAttr = originals.get(attr);
          if (cachedAttr === undefined || (currentAttr !== cachedAttr && !Object.values(dictionary).some(d => Object.entries(d).some(([key, value]) => currentAttr.trim() === value || currentAttr.trim() === key)))) originals.set(attr, currentAttr);
          const original = originals.get(attr) ?? "";
          const key = original.trim();
          const translated = normalizedTranslation(key, language);
          const sourceEnglish = Object.entries(dictionary).flatMap(([, entries]) => Object.entries(entries)).find(([, value]) => value === key)?.[0];
          const next = isEnglishOnlyLab(el) ? (sourceEnglish ? original.replace(key, sourceEnglish) : original) : (translated ? original.replace(key, translated) : original);
          if (el.getAttribute(attr) !== next) el.setAttribute(attr, next);
        }
      });
    };
    translate();
    const observer = new MutationObserver(() => { observer.disconnect(); translate(); observer.observe(document.body, {childList:true,subtree:true,characterData:true,attributes:true,attributeFilter:["placeholder","title","aria-label","alt"]}); });
    observer.observe(document.body, {childList:true,subtree:true,characterData:true,attributes:true,attributeFilter:["placeholder","title","aria-label","alt"]});
    return () => observer.disconnect();
  }, [language]);
  return (
    <div data-language-selector="" style={{position:"fixed",bottom:18,right:12,zIndex:2147483647,background:"#101a2c",color:"white",border:"1px solid #64748b",borderRadius:9,padding:"6px 10px",fontSize:13}}>
      <label htmlFor="site-language" style={{marginRight:6}}>🌐</label>
      <select id="site-language" aria-label="Website language" value={language} onChange={e=>setLanguage(e.target.value as Language)} style={{background:"#101a2c",color:"white",border:0}}>
        {languages.map(l=><option key={l.code} value={l.code}>{l.label}</option>)}
      </select>
    </div>
  );
}
